// First-run setup and repair. Safe to run again: it only creates what is missing, and
// refreshes app-generated files without losing anything a person edited.
import fs from 'node:fs'
import path from 'node:path'
import { APP_DIR, FOLDERS, dataDir, folder, rootDir } from './paths.mjs'
import { writeGenerated } from './archive.mjs'
import { buildCoverLetter, buildResume, loadFormat } from './docx.mjs'
import { openStore } from './store.mjs'

const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'))

export function ensureFolders() {
  const created = []
  for (const name of Object.keys(FOLDERS)) {
    const dir = folder(name)
    if (!fs.existsSync(dir)) { fs.mkdirSync(dir, { recursive: true }); created.push(FOLDERS[name]) }
  }
  fs.mkdirSync(dataDir(), { recursive: true })
  return created
}

export function rulesMarkdown(rules) {
  const lines = ['# Writing rules', '', 'Agents follow these when drafting resumes, CVs, cover letters and answers. This file is regenerated by the app; to change a rule, ask your assistant (for example "retire the bibliography rule").', '']
  const shown = (r) => (r.status === 'proposed' && r.active ? { ...r, ...r.active, status: r.active.status || 'approved', pending: r } : r)
  const all = rules.map(shown)
  for (const group of [['starter', 'On by default'], ['approved', 'Approved by you'], ['proposed', 'Suggested (not used until you approve them)'], ['retired', 'Retired']]) {
    const rows = all.filter((r) => r.status === group[0])
    if (!rows.length) continue
    lines.push(`## ${group[1]}`, '')
    for (const r of rows) {
      lines.push(`### ${r.title}`, '', r.rule, '')
      if (r.pending) lines.push(`*New wording waiting for your approval:* ${r.pending.rule}`, '')
      if (r.whenRelevant) lines.push(`*When:* ${r.whenRelevant}`, '')
      if (r.example) lines.push(`*Example (invented):* ${r.example}`, '')
    }
  }
  return lines.join('\n')
}

/** Write the Word masters, format files, rules and checklist into "4 Templates". */
export function writeTemplates(store) {
  const dir = folder('templates')
  const out = []
  for (const name of ['resume-format.json', 'cover-letter-format.json']) {
    const target = path.join(dir, name)
    if (!fs.existsSync(target)) { fs.copyFileSync(path.join(APP_DIR, 'templates', name), target, fs.constants.COPYFILE_EXCL); out.push(target) }
  }
  const resumeMaster = buildResume(read(path.join(APP_DIR, 'templates', 'resume-master.json')), loadFormat('resume'))
  const letterMaster = buildCoverLetter(read(path.join(APP_DIR, 'templates', 'cover-letter-master.json')), loadFormat('cover-letter'))
  out.push(writeGenerated(path.join(dir, 'Resume master.docx'), resumeMaster).path)
  out.push(writeGenerated(path.join(dir, 'Cover letter master.docx'), letterMaster).path)
  const demo = read(path.join(APP_DIR, 'demo', 'demo.json'))
  out.push(writeGenerated(path.join(dir, 'Examples', 'Example resume (fictional).docx'), buildResume(demo.exampleResume, loadFormat('resume'))).path)
  out.push(writeGenerated(path.join(dir, 'Examples', 'Example cover letter (fictional).docx'), buildCoverLetter(demo.exampleCoverLetter, loadFormat('cover-letter'))).path)
  out.push(writeGenerated(path.join(dir, 'Format Guide.md'), fs.readFileSync(path.join(APP_DIR, 'templates', 'format-guide.md'))).path)
  const checklist = read(path.join(APP_DIR, 'templates', 'review-checklist.json')).steps
  out.push(writeGenerated(path.join(dir, 'Review Checklist.md'), ['# Review checklist', '', 'Agents work through these steps before a document is ready for you to submit.', '', ...checklist.map((s, i) => `${i + 1}. ${s}`), ''].join('\n')).path)
  if (store) out.push(writeGenerated(path.join(dir, 'Writing Rules.md'), rulesMarkdown(store.rules())).path)
  return out
}

function loadDemo(store) {
  if (store.applications().length) return false
  const demo = read(path.join(APP_DIR, 'demo', 'demo.json'))
  store.t.transaction(() => {
    store.setProfile(demo.profile, { actor: 'demo' })
    for (const e of demo.employers) store.addEmployer(e, { actor: 'demo' })
    for (const a of demo.applications) store.addApplication(a, { actor: 'demo' })
    for (const r of demo.researchTasks) store.queueResearch(r, { actor: 'demo' })
    for (const e of demo.evidence) store.addEvidence(e, { actor: 'demo' })
    store.saveMaterial({ kind: 'resume', title: 'Example resume content (fictional)', content: JSON.stringify(demo.exampleResume, null, 2), reviewStatus: 'draft' }, { actor: 'demo' })
  })
  store.seedStarterRules()
  return true
}

/** Create folders, the database, starter rules, templates and the demo workspace. */
export function runSetup({ demo = true } = {}) {
  const report = { root: rootDir(), createdFolders: ensureFolders() }
  const store = openStore()
  try {
    report.rules = store.seedStarterRules()
    report.templates = writeTemplates(store).map((p) => path.relative(rootDir(), p))
    report.profileComplete = Boolean(store.profile()?.name)
  } finally {
    store.close()
  }
  if (demo) {
    const demoStore = openStore({ demo: true })
    try { report.demoLoaded = loadDemo(demoStore) } finally { demoStore.close() }
  }
  fs.writeFileSync(path.join(dataDir(), 'setup-state.json'), JSON.stringify({ completedAt: new Date().toISOString(), root: rootDir() }, null, 2))
  return report
}
